 const optsKeep=lang==='de'?['3 Sicherungen','5 Sicherungen','10 Sicherungen','12 Sicherungen','20 Sicherungen','50 Sicherungen']:['3 backups','5 backups','10 backups','12 backups','20 backups','50 backups'];Array.from($('#backupKeep').options).forEach((o,i)=>o.textContent=optsKeep[i]);
