  const params=new URLSearchParams();if(regionSel.value)params.set('region',regionSel.value);if(projectSel.value)params.set('project_id',projectSel.value);if($('#dashboardStatus').value)params.set('status',$('#dashboardStatus').value);
  const data=await api('/dashboard/projects'+(params.size?'?'+params.toString():''));dashboardItems=data.items;
