function validateStateGeoJSON(geo){if(!geo||geo.type!=='FeatureCollection'||!Array.isArray(geo.features)||geo.features.length<1||geo.features.length>5000)return 'Erwartet wird eine FeatureCollection mit 1 bis 5.000 Features.';for(let i=0;i<geo.features.length;i++){const f=geo.features[i];if(!f||f.type!=='Feature'||!f.geometry||!['Polygon','MultiPolygon'].includes(f.geometry.type)||!f.properties||typeof f.properties!=='object')return 'Feature '+(i+1)+' ist kein gültiges Polygon-Feature mit Eigenschaften.';const rings=f.geometry.type==='Polygon'?f.geometry.coordinates:f.geometry.coordinates.flat();if(!Array.isArray(rings)||!rings.length||rings.some(r=>!Array.isArray(r)||r.length<4||r.some(c=>!Array.isArray(c)||c.length<2||!Number.isFinite(Number(c[0]))||!Number.isFinite(Number(c[1]))||Number(c[0]) < -180||Number(c[0]) > 180||Number(c[1]) < -90||Number(c[1]) > 90)))return 'Feature '+(i+1)+' enthält ungültige WGS84-Koordinaten.';}return '';}
