async function refreshNews(silent=false){
 const owner=!newsRefreshPromise,button=$('#refreshNews');
 if(owner){
  if(button)button.disabled=true;
  const request=(async()=>{const res=await api('/news?refresh=1');newsItems=Array.isArray(res.items)?res.items:[];newsSources=Array.isArray(res.sources)?res.sources:[];renderNews();renderRegionNews();$('#newsState').textContent=res.errors?.length?(lang==='de'?'TEILWEISE':'PARTIAL'):(lang==='de'?'AKTUELL':'CURRENT');return res;})();
  newsRefreshPromise=request;
 }
 const request=newsRefreshPromise;
 try{
  const res=await request;
  if(!silent){notify(res.errors?.length?(lang==='de'?'Feeds aktualisiert; einzelne Quellen nicht erreichbar.':'Feeds refreshed; some sources are unreachable.'):(lang==='de'?'RSS-Feeds aktualisiert.':'RSS feeds refreshed.'));if(res.errors?.length)console.info('RSS-Status',res.errors);}
  return res;
 }catch(e){if(!silent)notify((lang==='de'?'Nachrichten konnten nicht aktualisiert werden: ':'News refresh failed: ')+e.message,'error');return null}
 finally{if(owner){if(newsRefreshPromise===request)newsRefreshPromise=null;if(button)button.disabled=false;}}
}
