async function loadOperations(){
 try{
  const [u,r,a]=await Promise.all([api('/units'),api('/resources'),api('/assignments')]);
  operationUnits=u.items;operationResources=r.items;operationAssignments=a.items;
  const projects=await api('/records?module=projects');operationProjects=projects.items;
  $('#unitHeading').textContent=settings.unit_label_plural||'Mitglieder';$('#unitCount').textContent=String(operationUnits.length).padStart(2,'0');$('#resourceCount').textContent=String(operationResources.length).padStart(2,'0');$('#assignmentCount').textContent=String(operationAssignments.length).padStart(2,'0');
  $('#unitList').innerHTML=operationUnits.length?operationUnits.map(x=>`<article class="ops-item"><div class="ops-item-head"><strong>${esc(x.name)}</strong><button class="btn ghost small" data-delete-unit="${x.id}" aria-label="Profil löschen">×</button></div><div class="ops-meta">${esc(x.role||'—')} · ${esc(x.status||'Aktiv')} · ${esc(x.region||'ohne Region')}</div><p>${esc(x.biography||'Keine Biografie hinterlegt.')}</p>${x.tags?.length?`<div class="tag-list">${x.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}</article>`).join(''):'<div class="empty">Noch keine Profile angelegt.</div>';
  $('#resourceList').innerHTML=operationResources.length?operationResources.map(x=>`<article class="ops-item"><div class="ops-item-head"><strong>${esc(x.name)}</strong><button class="btn ghost small" data-delete-resource="${x.id}" aria-label="Ressource löschen">×</button></div><div class="ops-meta">${esc(x.category||'Allgemein')} · ${esc(x.location||'ohne Standort')}</div><p><strong class="resource-amount">${esc(String(x.quantity))} ${esc(x.unit)}</strong>${x.notes?` — ${esc(x.notes)}`:''}</p></article>`).join(''):'<div class="empty">Noch keine Ressourcen eingetragen.</div>';
  $('#assignmentProject').innerHTML='<option value="">Projekt auswählen…</option>'+operationProjects.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('');
  updateAssignmentTargets();
  $('#assignmentList').innerHTML=operationAssignments.length?operationAssignments.map(x=>`<article class="ops-item"><div class="ops-item-head"><strong>${esc(x.project_title)}</strong><button class="btn ghost small" data-delete-assignment="${x.id}" aria-label="Zuweisung löschen">×</button></div><div class="ops-meta">${esc(x.unit_name||x.resource_name||'Unbekannt')} · ${esc(String(x.quantity))}${x.unit_name?' Person(en)':''}</div>${x.notes?`<p>${esc(x.notes)}</p>`:''}</article>`).join(''):'<div class="empty">Noch keine Projektzuweisungen.</div>';
  $$('[data-delete-unit]').forEach(b=>b.addEventListener('click',()=>deleteOperationItem('units',b.dataset.deleteUnit,'Profil wirklich löschen?')));
  $$('[data-delete-resource]').forEach(b=>b.addEventListener('click',()=>deleteOperationItem('resources',b.dataset.deleteResource,'Ressource wirklich löschen?')));
  $$('[data-delete-assignment]').forEach(b=>b.addEventListener('click',()=>deleteOperationItem('assignments',b.dataset.deleteAssignment,'Zuweisung wirklich löschen?')));
 }catch(e){notify('Personal & Logistik konnten nicht geladen werden: '+e.message,'error')}
}
